def forward_until(self, condition):
        """Forward until one of the provided matches is found.

        The returned string contains all characters found *before the condition
        was met. In other words, the condition will be true for the remainder
        of the buffer.

        :param condition: set of valid strings
        """
        max_len = max((len(s) for s in condition), default=0)
        # Immediate match if empty string is a condition
        if "" in condition:
            return ""
        result_parts = []
        while True:
            # Look ahead up to the longest possible condition string
            if max_len:
                ahead = self.peek(max_len)
                for cand in condition:
                    if ahead.startswith(cand):
                        return "".join(result_parts)
            # Consume next character; stop if EOF
            nxt = self.read(1)
            if not nxt

