    if 'hmtx' in ttFont:
        try:
            hmtx = ttFont['hmtx'].metrics
        except Exception:
            hmtx = {}

    # Collect widths for ASCII glyphs (0x20‑0x7E)
    widths = []
    for cp in range(0x20, 0x7F):
        glyph_name = cmap.get(cp)
        if glyph_name is None:
