def render_html(root, options=0, extensions=None):
    """Render a given syntax tree as HTML.

    Args:
        root (Any): The reference to the root node of the syntax tree.
        options (int): The cmark options.
        extensions (Any): The reference to the syntax extensions, generally
            from :func:`parser_get_syntax_extensions`

    Returns:
        str: The rendered HTML.
    """
        if node is None:
            return ''
        # If node is a plain string, return escaped HTML
        if isinstance(node, str):
            import html
            return html.escape(node)
        # If node provides its own rendering method
        if hasattr(node, 'render'):
            return node.render()
        # If node is a dict representing a syntax node
        if isinstance(node, dict):
            t = node.get('type')
            children = node.get('children', [])
            if t == 'text':
                import html
                return html.escape(node.get('literal', ''))
            if t == 'paragraph':
                return f"<p>{''.join(_render(c) for c in children)}</p>"
            if t == 'heading':
                level = node.get('level', 1)
                level = max(1, min(6, level))
                return f"<h{level}>{''.join(_render(c) for c in children)}</h{level}>"
            if t == 'list':
                tag = 'ol' if node.get('ordered', False) else 'ul'
                return f"<{tag}>{''.join(_render(c) for c in children)}</{tag}>"
            if t == 'item':
                return f"<li>{''.

