def rate_limit(f):
    """
    A decorator to handle rate limiting from the Twitter API. If
    a rate limit error is encountered we will sleep until we can
    issue the API call again.
    """
    import time
    import functools
    try:
        from tweepy.errors import RateLimitError
    except Exception:
        RateLimitError = None

    @functools.wraps(f)
    def wrapper(*args, **kwargs):
        while True:
            try:
                return f(*args, **kwargs)
            except Exception as e:
                wait = None
                # Tweepy specific RateLimitError
                if RateLimitError is not None and isinstance(e, RateLimitError):
                    # Tweepy RateLimitError may have a 'retry_after' attribute (seconds)
                    wait = getattr(e, "retry_after", None)
                # Generic HTTP response with rate limit reset header
                if wait is None and hasattr(e, "response"):
                    resp = e.response
                    headers = getattr(resp, "headers", {})
