    * desc (str): The description of the arg (optional).
    * type (type, CustomType, callable): The alias for the task (optional).

  Notes:
    * It always follows a @task or an @arg.
  """
    if callable(name):
        # Used as @arg without parentheses
        return _arg()(name)
    def _decorator(func):
        if name is not None:
            return _arg(name, **Config)(func)
        return _arg(**Config)(func)
