        if time_grouping == 1:
            return timeperiod

        # Preserve original type (int or str) while performing arithmetic
        try:
            tp_int = int(timeperiod)
        except Exception as exc:
            raise ValueError("timeperiod must be an integer or integer‑convertible string") from exc

