    if 'opcode' not in op_data:
        raise ValueError("op_data missing required field 'opcode'")
    if opcode != op_data['opcode']:
        raise ValueError(f"Opcode mismatch: expected {op_data['opcode']}, got {opcode}")

    # Verify preorder_record contains the expected history_id and opcode
    if 'history_id' not in preorder_record:
        raise ValueError("preorder_record missing required field 'history_id'")
    if 'opcode' not in preorder_record:
        raise ValueError("preorder_record missing required field 'opcode'")
