        raise ValueError(f"History ID mismatch: expected {preorder_record['history_id']}, got {history_id}")
    if opcode != preorder_record['opcode']:
        raise ValueError(f"Preorder opcode mismatch: expected {preorder_record['opcode']}, got {opcode}")

