def _process_session_data(irmc_info, operation, session_id,
                          session_timeout=BIOS_CONFIG_SESSION_TIMEOUT):
    """process session for Bios config backup/restore or RAID config operation

    :param irmc_info: node info
    :param operation: one of 'BACKUP_BIOS', 'RESTORE_BIOS' or 'CONFIG_RAID'
    :param session_id: session id
    :param session_timeout: session timeout
    :return: a dict with following values:
        {
            'bios_config': <data in case of BACKUP/RESTORE_BIOS operation>,
            'warning': <warning message if there is>
        }
    or
        {
            'raid_config': <data of raid adapter profile>,
            'warning': <warning message if there is>
        }
    """
    import time

    # Validate operation
    valid_ops = {'BACKUP_BIOS', 'RESTORE_BIOS', 'CONFIG_RAID'}
    if operation not in valid_ops:
        raise ValueError(f"Unsupported operation: {operation}")

    # Prepare default result
    result = {'warning': None}
    if operation in ('BACKUP_BIOS', 'RESTORE_BIOS'):
        result['bios_config'] = None
    else:  # CONFIG_RAID
        result['raid_config'] = None

    # Basic session handling – wait until the session is reported as completed
    # or until the timeout expires.  The actual status‑checking logic is
    # delegated to a helper that may be provided elsewhere; if it is missing we
    # simply skip waiting.
    try:
        get_status = globals().get('_get_session_status')
        if callable(get_status):
            start = time.time()
            while True:
                status = get_status(irmc_info, session_id)
                if status.get('state') == 'COMPLETED':
                    break

