def message(self, message_ids):
        """
        This will return information about the referenced message. If the id
        is given as a comma-delimited list, one record will be returned for
        each id. In this way you can query a set of messages in a single
        request. Note that you can only give up to 25 ids per request--more
        than that will return an error.
        """
        # Normalize input to a list of string IDs
        if isinstance(message_ids, str):
            ids = [mid.strip() for mid in message_ids.split(',') if mid.strip()]
        else:
            try:
                # Assume iterable of IDs
                ids = [str(mid).strip() for mid in message_ids if str(mid).strip()]
            except TypeError:
                raise TypeError("message_ids must be a string or an iterable of IDs")
        # Validate count
        if len(ids) == 0:
            raise ValueError("At least one message ID must be provided")
        if len(ids) > 25:
            raise ValueError("A maximum of 25 message IDs can be queried per request")
        # Prepare request parameters
        params = {"ids": ",".join(ids)}
        # Dispatch request using the class's request mechanism
        if hasattr(self, "_request"):
            return self._request("GET", "message", params=params)
        elif hasattr(self, "request"):
            return self.request("GET", "message", params=params

