def create_role(resource_root,
                service_name,
                role_type,
                role_name,
                host_id,
                cluster_name="default"):
  """
  Create a role
  @param resource_root: The root Resource object.
  @param service_name: Service name
  @param role_type: Role type
  @param role_name: Role name
  @param cluster_name: Cluster name
  @return: An ApiRole object
  """
    # Attempt to retrieve the service directly from the resource root
    try:
        service = resource_root.get_service(service_name)
    except Exception:
        # Fallback: retrieve the cluster first, then the service within it
        cluster = resource_root.get_cluster(cluster_name)
        service = cluster.get_service(service_name)

    # Create the role using the service object
    role = service.create_role(role_name, role_type, host_id)

    return role

