def remove_node(self, node, stop=False):
        """Removes a node from the cluster.

        By default, it doesn't also stop the node, just remove from
        the known hosts of this cluster.

        :param node: node to remove
        :type node: :py:class:`Node`

        :param stop: Stop the node
        :type stop: bool

        """
        # Remove node from the cluster's node collection
        removed = False
        if hasattr(self, "nodes"):
            try:
                self.nodes.remove(node)
                removed = True
            except ValueError:
                pass

        # Remove node from known hosts if such a collection exists
        if hasattr(self, "known_hosts"):
            try:
                # set‑like
                self.known_hosts.discard(node)  # type: ignore[attr-defined]
            except AttributeError:
                try:
                    # dict‑like
                    self.known_hosts.pop(node, None)  # type: ignore[attr-defined]
                except Exception:
                    pass

        # Optionally stop the node
        if stop:
            try:
                node.stop()
            except Exception as exc:
                raise RuntimeError(f"Failed to stop node {node!r}") from exc

        if not removed

