        :param cb_type: Constants.CB_TYPE_DIRECT = direct call or
                        Constants.CB_TYPE_ASYNCIO = asyncio coroutine

        :returns: No return value
        """
        # Validate pin number
        if not isinstance(pin_number, int) or pin_number < 0:
            raise ValueError("pin_number must be a non‑negative integer")
        # Validate pin state
        valid_states = {"INPUT", "OUTPUT", "ANALOG", "PWM", "PULLUP"}
        if pin_state not in valid_states:
            raise ValueError(f"pin_state must be one of {valid_states}")
        # Build and send the command to the device
        cmd = f"SET_PIN_MODE {pin_number} {pin_state}"
        if hasattr(self, "_write"):
            self._write(cmd)
        elif hasattr(self, "send"):
            self.send(cmd)
